const shell = (content) => `<a class="skip-link" href="#main">К содержанию</a><header class="header"><div class="container header__row"><a class="brand" href="/" aria-label="Сервисы альтернативной оплаты">${logo}</a><nav class="nav" aria-label="Основная навигация">${navigation.map(([label, href]) => `<a href="${href}" ${isCurrentSitePath(href) ? 'aria-current="page"' : ''}>${label}</a>`).join('')}</nav><a class="dzen" href="#" aria-label="Мы в Дзене">${dzenHeaderIcon}</a><a class="header__cta" href="/contacts.html">Добавить сервис</a><button class="menu-button" data-mobile-menu aria-expanded="false" aria-controls="mobile-nav" aria-label="Открыть меню">☰</button></div><nav class="mobile-nav" id="mobile-nav" hidden aria-label="Мобильная навигация">${navigation.map(([label, href]) => `<a href="${href}" ${isCurrentSitePath(href) ? 'aria-current="page"' : ''}>${label}</a>`).join('')}<a href="/contacts.html">Добавить сервис</a></nav></header><main id="main">${content}</main><footer class="footer"><div class="container footer__top"><div><a class="brand" href="/" aria-label="Сервисы альтернативной оплаты">${logo}</a><p>Сайт носит информационный характер и не является платёжным сервисом. Мы не принимаем платежи и не оказываем финансовых услуг. Оценки отражают мнение редакции и пользователей на дату публикации; условия сервисов могут измениться без предупреждения.</p></div><a class="header__cta footer__cta" href="/contacts.html">Добавить сервис</a></div><div class="container footer__grid"><div><strong>Информация</strong><a href="/methodology.html">Методика проверки</a><a href="/contacts.html">Контакты</a></div><div><strong>Сервисам</strong><a href="/contacts.html">Добавить сервис</a><a href="/advertising.html">Реклама</a></div></div><div class="container footer__bottom"><a class="footer__dzen" href="#">${dzenFooterIcon}<span>Мы в Дзене</span></a><a href="/agreement.html">Пользовательское соглашение</a><span>© 2022 — 2026</span></div></footer>`;
